import {NEIGHBOR_SIDES,neighborSupply} from './neighbor-economies.js?v=neighbor-economies-1';
import {connectionCandidates,addConnection,signDeal,cancelDeal,connected,terminationFee,NEIGHBORS} from './region.js?v=neighbor-economies-1';
import {recompute} from './engine.js?v=neighbor-economies-1';
export function showRegion(ui){const {city,dialog,update,save,clearUndo,notify}=ui,c=city(),$=s=>document.querySelector(s),fmt=v=>'§'+Math.round(v).toLocaleString(),candidates=connectionCandidates(c).filter(p=>!c.region.connections.some(e=>e.tile===p.tile&&e.kind===p.kind)),label=p=>`${NEIGHBORS[p.side]} · ${p.kind} · tile ${p.tile%48+1}, ${Math.floor(p.tile/48)+1}`;
 dialog('Neighbors & utility deals',`<p>Run a power line, pipe, road, highway or rail to a dry map boundary, then complete the neighbor connection here. Operating seaports can connect through navigable water. Each connection costs §100.</p><h3>Regional cities</h3><div class="table-scroll"><table><thead><tr><th>Neighbor</th><th>Population</th><th>Treasury</th><th>Power surplus</th><th>Water surplus</th><th>Disposal space</th><th>Last trade balance</th></tr></thead><tbody>${NEIGHBOR_SIDES.map(side=>{const n=c.region.neighbors[side];return `<tr><td>${NEIGHBORS[side]}</td><td>${side==='sea'?'Port network':Math.round(n.population).toLocaleString()}</td><td>${fmt(n.treasury)}</td><td>${neighborSupply(c,side,'power').toFixed(1)}</td><td>${neighborSupply(c,side,'water').toFixed(1)}</td><td>${neighborSupply(c,side,'garbage').toFixed(1)}</td><td>${fmt(n.lastTradeBalance)}</td></tr>`;}).join('')}</tbody></table></div><p>Neighbors grow and fund capacity from their own budgets. Their residents use utilities first; exports to you use remaining capacity. Resource and disposal shortages can reduce deliveries without charging you a supply-failure penalty. Regional values update monthly. Last trade balance is money received by that neighbor from our deals, minus payments to us.</p><label>Available border routes<select id="neighborRoute">${candidates.map((p,i)=>`<option value="${i}">${label(p)}</option>`).join('')||'<option value="">No unconnected border routes</option>'}</select></label><button id="connectNeighbor" ${candidates.length?'':'disabled'}>Complete connection · §100</button><h3>Proposed contract</h3><label>Connection<select id="dealConnection">${c.region.connections.map((p,i)=>`<option value="${i}" ${connected(c,p)?'':'disabled'}>${label(p)}${connected(c,p)?'':' · disconnected'}</option>`).join('')||'<option value="">Build a connection first</option>'}</select></label><label>Direction<select id="dealDirection"><option value="import">Import</option><option value="export">Export</option></select></label><label>Fixed monthly quantity for sales / incoming garbage<select id="dealAmount"><option value="25">25 units</option><option value="50" selected>50 units</option><option value="100">100 units</option></select></label><p id="dealTerms"></p><button id="acceptDeal" class="primary" ${c.region.connections.length?'':'disabled'}>Accept contract</button><h3>Active deals</h3>${c.region.deals.map(d=>{const con=c.region.connections[d.connection],buys=d.kind==='garbage'?d.direction==='export':d.direction==='import';return `<article class="milestone"><strong>${NEIGHBORS[con.side]} · ${d.direction} ${d.kind}</strong><p>${d.failed?'Connection or capacity failure: this deal will end with a penalty at the next monthly settlement.':`${d.delivered.toFixed(1)} units ${d.kind==='garbage'?'last month':'currently delivered'}. ${buys?'You pay':'You receive'} ${fmt(buys?Math.max(d.minFee,d.delivered*d.rate):d.amount*d.rate)}/month.`}</p><p>${c.month>=d.issuedMonth+12?'Annual review reached: voluntary termination is free.':`Free termination after ${d.issuedMonth+12-c.month} more months.`}</p><button data-cancel-deal="${d.id}">End deal · ${fmt(terminationFee(c,d))}</button></article>`;}).join('')||'<p>No contracts signed.</p>'}<h3>How deals work</h3><ul><li>Power and water imports cover the deficit on the connected network, limited by the neighbor’s available surplus. Unconnected districts receive nothing. A minimum fee applies even with zero usage.</li><li>Power and water exports require local capacity for your city plus the promised quantity. A broken connection or supply shortage cancels the deal with a penalty.</li><li>Garbage exports remove connected excess waste after local landfills have collected what they can, up to remaining neighbor disposal space. Undelivered waste stays in your city. Incoming garbage arrives at the connection, up to the agreed quantity and the neighbor’s available waste, and needs connected disposal capacity. Payments follow actual delivery.</li><li>Rail freight requires a connected train station linking the tracks to local roads. Seaports use their local road access.</li></ul><p>Regional income: ${fmt(c.stats.regionIncome)}/month. Charges: ${fmt(c.stats.regionExpense)}/month. Garbage projections use the previous collection; the actual bill changes with waste. Penalties paid: ${fmt(c.region.totalPenalties)}.</p><p class="fine">One deal per resource is supported. Neighbor names, prices and annual review terms are provisional; neighbor populations, budgets, growth, resource use and investment are original aggregate simulations, not full neighboring tile maps or recovered original formulas.</p>`);
 function draft(){const index=Number($('#dealConnection').value),con=c.region.connections[index];return{index,con,kind:con&&['power','water'].includes(con.kind)?con.kind:'garbage',direction:$('#dealDirection').value,amount:Number($('#dealAmount').value)};}
 function terms(){const d=draft();if(!d.con){$('#dealTerms').textContent='Connect a border route to receive an offer.';return;}const buys=d.kind==='garbage'?d.direction==='export':d.direction==='import',rate=d.kind==='power'?(buys?.5:.4):d.kind==='water'?(buys?.3:.2):2,min=d.kind==='garbage'?15:10,fee=Math.ceil(Math.max(min,d.amount*rate)*12);$('#dealTerms').textContent=`${d.direction==='import'?'Import':'Export'} ${d.kind}: ${buys?`pay §${rate} per delivered unit (minimum ${fmt(min)}/month)`:`receive ${fmt(d.amount*rate)}/month for ${d.amount} units`}. ${buys?'Quantity follows connected demand or excess garbage, limited by neighbor capacity.':'You must fulfill the fixed quantity.'} Early cancellation costs ${fmt(fee)}; voluntary termination is free after twelve months. Supply failure or connection loss carries the full penalty.`;}
 function changed(){clearUndo();recompute(c);update();save();showRegion(ui);}
 $('#connectNeighbor').onclick=()=>{const p=candidates[Number($('#neighborRoute').value)];if(!p)return;const r=addConnection(c,p);if(!r.ok)return notify(r.error);notify('Neighbor connection completed.');changed();};$('#acceptDeal').onclick=()=>{const d=draft(),before=structuredClone(c.region),r=signDeal(c,d.index,d.kind,d.direction,d.amount);if(!r.ok)return notify(r.error);recompute(c);if(c.region.deals.at(-1).failed){c.region=before;recompute(c);return notify('There is not enough connected surplus to fulfill this offer. Add capacity first.');}notify('Neighbor contract accepted.');changed();};document.querySelectorAll('[data-cancel-deal]').forEach(b=>b.onclick=()=>{const r=cancelDeal(c,Number(b.dataset.cancelDeal));if(!r.ok)return notify(r.error);notify(`Deal ended. Fee: ${fmt(r.fee)}.`);changed();});for(const id of ['dealConnection','dealDirection','dealAmount'])$('#'+id).onchange=terms;terms();
}
